156	    /**
157	     * Set the first line of the owner's structured address, normalized the same way
158	     * as the flat {@link #setAddress(String)} (trimmed, whitespace collapsed,
159	     * upper-cased, street-type abbreviations expanded). A {@code null} value is left
160	     * as-is.
