179	    /**
180	     * Normalize an address string to its canonical form: trimmed, whitespace
181	     * collapsed, upper-cased, with common street-type abbreviations expanded.
182	     * Returns {@code null} for a {@code null} input; a value that is blank once
183	     * trimmed normalizes to the empty string.
184	     */
185	    public static String normalizeAddress(String address) {
186	        if (address == null) {
187	            return null;
188	        }
189	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
190	        if (collapsed.isEmpty()) {
191	            return "";
192	        }
193	        String[] tokens = collapsed.split(" ");
194	        StringBuilder sb = new StringBuilder();
195	        for (int i = 0; i < tokens.length; i++) {
196	            if (i > 0) {
197	                sb.append(' ');
198	            }
199	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
200	        }
201	        return sb.toString();
202	    }
