220	    /**
221	     * Return the stored E.164 telephone formatted for humans: a {@code '+'} and the
222	     * country code, a space, then the national digits grouped in threes and separated
223	     * by single spaces (for example {@code '+61412345678' -> '+61 412 345 678'}). The
224	     * North American country code ({@code '+1'}) is one digit; other country codes are
225	     * taken as two. Returns {@code null} when the telephone is not set, and returns the
226	     * raw value unchanged when it is not a well-formed E.164 number.
227	     */
228	    public String getTelephoneDisplay() {
229	        if (this.telephone == null || !this.telephone.matches("^\\+[0-9]+$")) {
230	            return this.telephone;
231	        }
232	        String digits = this.telephone.substring(1);
233	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
234	        if (digits.length() <= countryCodeLength) {
235	            return this.telephone;
236	        }
237	        String countryCode = digits.substring(0, countryCodeLength);
238	        String national = digits.substring(countryCodeLength);
239	        StringBuilder sb = new StringBuilder("+").append(countryCode);
240	        for (int i = 0; i < national.length(); i += 3) {
241	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
242	        }
243	        return sb.toString();
244	    }
