303	     * Whether this owner's postcode is valid for its city. A {@code null} postcode
304	     * is always valid (postcode is optional). When present, a postcode is valid if
305	     * the city has no known region, or if it is four digits falling within the
306	     * inclusive range for the city's region ({@code Sydney -> NSW 2000-2099},
307	     * {@code Melbourne -> VIC 3000-3099}, {@code Brisbane -> QLD 4000-4099}).
308	     */
309	    public boolean isPostcodeValidForCity() {
310	        if (this.postcode == null) {
311	            return true;
312	        }
313	        String region = CITY_REGION.get(this.city);
314	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
315	        if (range == null) {
316	            return true;
317	        }
318	        if (!this.postcode.matches("^[0-9]{4}$")) {
319	            return false;
320	        }
321	        int value = Integer.parseInt(this.postcode);
322	        return value >= range[0] && value <= range[1];
