333	    /**
334	     * Return a single Luhn check digit (0-9) computed over the digits contained in
335	     * the owner's customer code, or {@code null} when the customer code is not set.
336	     * Non-digit characters in the code are ignored; the rightmost digit is doubled
337	     * first, following the standard Luhn algorithm.
338	     */
339	    public Integer getCheckDigit() {
340	        if (this.customerCode == null) {
341	            return null;
342	        }
343	        int sum = 0;
344	        boolean doubleDigit = true;
345	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
346	            char c = this.customerCode.charAt(i);
347	            if (c < '0' || c > '9') {
348	                continue;
349	            }
350	            int digit = c - '0';
351	            if (doubleDigit) {
352	                digit *= 2;
353	                if (digit > 9) {
354	                    digit -= 9;
355	                }
356	            }
357	            sum += digit;
358	            doubleDigit = !doubleDigit;
359	        }
360	        return (10 - (sum % 10)) % 10;
361	    }
