389	     * Return the owner's membership points, the raw score from which the
390	     * membership level is derived. Starting at {@code 0}, add {@code 2} when an
391	     * email address is present, {@code 1} when the owner has no namesakes
392	     * (namesake count is {@code 0}), {@code 2} for a household of {@code 3} or
393	     * more, and {@code 3} when the owner's tenure (days since the registration
394	     * date) exceeds {@code 365}.
395	     */
396	    public Integer getMembershipPoints() {
397	        int points = 0;
398	        boolean hasEmail = this.email != null && !this.email.isBlank();
399	        if (hasEmail) {
400	            points += 2;
401	        }
402	        if (this.namesakeCount != null && this.namesakeCount == 0) {
403	            points += 1;
404	        }
405	        if (this.householdSize != null && this.householdSize >= 3) {
406	            points += 2;
407	        }
408	        if (this.registrationDate != null
409	                && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
410	            points += 3;
411	        }
412	        return points;
413	    }
