415	    /**
416	     * Return the owner's membership level, a number from {@code 1} to {@code 4},
417	     * derived from {@link #getMembershipPoints()}: {@code 1} for {@code 0-1}
418	     * points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
419	     * {@code 4} for {@code 6} or more.
420	     */
421	    public Integer getMembershipLevel() {
422	        int points = getMembershipPoints();
423	        if (points >= 6) {
424	            return 4;
425	        }
426	        if (points >= 4) {
427	            return 3;
428	        }
429	        if (points >= 2) {
430	            return 2;
431	        }
432	        return 1;
433	    }
