474	     * Whether more than 80 owners had already been registered on this owner's
475	     * registration day at the time it was created, flagging a bulk-signup surge.
476	     */
477	    public Boolean getBulkSignupWarning() {
478	        return this.bulkSignupWarning;
479	    }
480	
481	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
482	        this.bulkSignupWarning = bulkSignupWarning;
483	    }
484	
485	    /**
486	     * Return the owner's locality (region), preferring the postcode: when the
487	     * postcode is present and falls within a known region's inclusive range
488	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), that
489	     * region is returned. Otherwise the value falls back to the fixed
490	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
491	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the
492	     * table. This yields the same region for known cities but disambiguates
493	     * cities that share a name.
494	     */
495	    public String getLocality() {
496	        String regionFromPostcode = regionForPostcode();
497	        if (regionFromPostcode != null) {
498	            return regionFromPostcode;
499	        }
500	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
501	    }
502	
503	    /**
504	     * Return the owner's IANA timezone, derived from the locality/region via the
505	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
506	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or
507	     * {@code null} when the region is not in the table.
508	     */
509	    public String getTimezone() {
510	        return REGION_TIMEZONE.get(getLocality());
511	    }
512	
513	    /**
514	     * Look up the region whose inclusive postcode range contains this owner's
515	     * postcode, or {@code null} when the postcode is absent, malformed, or in no
516	     * known range.
517	     */
518	    private String regionForPostcode() {
519	        if (this.postcode == null || !this.postcode.matches("^[0-9]{4}$")) {
520	            return null;
521	        }
522	        int value = Integer.parseInt(this.postcode);
523	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
524	            int[] range = entry.getValue();
525	            if (value >= range[0] && value <= range[1]) {
526	                return entry.getKey();
527	            }
528	        }
529	        return null;
530	    }
531	
532	    /**
533	     * Return the owner's preferred contact channel, derived from the stored
534	     * contact details: {@code 'EMAIL'} when an email address is present,
535	     * otherwise {@code 'PHONE'}.
536	     */
