52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Dedicated audit trail for owner-lifecycle side effects. */
66	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
67	
68	    /** Email domains from disposable/throwaway providers, rejected on create. */
69	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
70	        "mailinator.com", "tempmail.com", "guerrillamail.com");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
119	        if (normalizedTelephone == null) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        if (isDisposableEmailDomain(ownerFieldsDto.getEmail())) {
123	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
124	        }
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        // The owner must supply an address in EITHER form: a non-blank structured
127	        // 'addressLine1' or the flat 'address'. getAddress() prefers the structured
128	        // fields (composing line 1 with an optional line 2) and falls back to the flat
129	        // value; a blank result means neither form was provided. The composed value is
130	        // written back so the persisted flat 'address' stays consistent with it.
131	        String composedAddress = owner.getAddress();
132	        if (composedAddress == null || composedAddress.isBlank()) {
133	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
134	        }
135	        owner.setAddress(composedAddress);
136	        owner.setTelephone(normalizedTelephone);
137	        if (!owner.isPostcodeValidForCity()) {
138	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
139	        }
140	        // The household id is deterministic: it is derived purely from the owner's
141	        // (last name, postcode), so every owner at the same last name and postcode resolves
142	        // to the same value. It is assigned up front, before any duplicate detection, so the
143	        // identity key and the household check below both key off it.
144	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
145	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
146	        // Consolidated hard-duplicate detection: reject only when the new owner's WHOLE
147	        // identityKey (telephone|email|householdId) equals an existing owner's. With the
148	        // household id now computed up front, two members of one household still differ here
149	        // whenever their telephone or email differs, and so are both allowed.
150	        String identityKey = owner.getIdentityKey();
151	        if (this.clinicService.findAllOwners().stream()
152	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
153	            return new ResponseEntity<>(HttpStatus.CONFLICT);
154	        }
155	        // Household duplicate: because the household is keyed on (last name, postcode), any
156	        // existing owner sharing this computed household id is the same household. A second
157	        // such owner is rejected as a household duplicate (409) unless it explicitly declares
158	        // 'sharesHousehold', which now only bypasses this block (the link is no longer created
159	        // here — the id is computed).
160	        List<Owner> householdMembers = findHouseholdMembers(owner.getHouseholdId());
161	        if (!householdMembers.isEmpty() && !sharesHousehold) {
162	            return new ResponseEntity<>(HttpStatus.CONFLICT);
163	        }
164	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
165	            return new ResponseEntity<>(HttpStatus.CONFLICT);
166	        }
167	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
168	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
169	        }
170	        LocalDate effectiveDate =
171	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
172	        LocalDate registrationDate = toBusinessDay(effectiveDate);
173	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
174	        if (ownersRegisteredToday >= 100) {
175	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
176	        }
177	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
178	        HttpHeaders headers = new HttpHeaders();
179	        owner.setRegistrationDate(registrationDate);
180	        owner.setCustomerCode(customerCode(owner));
181	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
182	        owner.setBulkSignupWarning(bulkSignupWarning);
183	        // The household size (an input to the membership computation) keys off the computed
184	        // household id: this owner plus everyone already sharing it.
185	        owner.setHouseholdSize(householdMembers.size() + 1);
186	        // Soft-match ("possible duplicate"): a declared household member is not a suspected
187	        // duplicate, so only a non-declared create is scored. In practice a non-declared owner
188	        // sharing an existing owner's last name and postcode is already rejected above as a
189	        // household duplicate, so this now only ever confirms the owner is not a duplicate.
190	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
191	        owner.setPossibleDuplicate(possibleDuplicate != null);
192	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
193	        this.clinicService.saveOwner(owner);
194	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
195	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
196	            owner.getMembershipNumber());
197	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
198	        headers.setLocation(UriComponentsBuilder.newInstance()
199	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
200	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
206	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
207	        if (currentOwner == null) {
208	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	        }
210	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
211	        if (normalizedTelephone == null) {
212	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
213	        }
214	        currentOwner.setAddress(ownerFieldsDto.getAddress());
215	        currentOwner.setCity(ownerFieldsDto.getCity());
216	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
217	        currentOwner.setLastName(ownerFieldsDto.getLastName());
218	        currentOwner.setTelephone(normalizedTelephone);
219	        currentOwner.setEmail(ownerFieldsDto.getEmail());
220	        this.clinicService.saveOwner(currentOwner);
221	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Transactional
226	    @Override
227	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
228	        Owner owner = this.clinicService.findOwnerById(ownerId);
229	        if (owner == null) {
230	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	        }
232	        this.clinicService.deleteOwner(owner);
233	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
234	    }
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
239	        Owner owner = this.clinicService.findOwnerById(ownerId);
240	        if (owner == null) {
241	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
242	        }
243	        HttpHeaders headers = new HttpHeaders();
244	        Pet pet = petMapper.toPet(petFieldsDto);
245	        owner.setId(ownerId);
246	        pet.setOwner(owner);
247	        pet.getType().setName(null);
248	        this.clinicService.savePet(pet);
249	        PetDto petDto = petMapper.toPetDto(pet);
250	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
251	            .buildAndExpand(pet.getId()).toUri());
252	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
253	    }
254	
255	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
256	    @Override
257	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
258	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
259	        if (currentOwner != null) {
260	            Pet currentPet = this.clinicService.findPetById(petId);
261	            if (currentPet != null) {
262	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
263	                currentPet.setName(petFieldsDto.getName());
264	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
265	                this.clinicService.savePet(currentPet);
266	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
267	            }
268	        }
269	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
270	    }
271	
272	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
273	    @Override
274	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
275	        HttpHeaders headers = new HttpHeaders();
276	        Visit visit = visitMapper.toVisit(visitFieldsDto);
277	        Pet pet = new Pet();
278	        pet.setId(petId);
279	        visit.setPet(pet);
280	        this.clinicService.saveVisit(visit);
281	        VisitDto visitDto = visitMapper.toVisitDto(visit);
282	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
283	            .buildAndExpand(visit.getId()).toUri());
284	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
285	    }
286	
287	
288	    /**
289	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
290	     * stripped. When a leading {@code '+'} and country code are present they are kept;
291	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
292	     * is dropped from the national digits. The result must be a {@code '+'} followed
293	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
294	     * is returned to signal a bad request.
295	     */
296	    /**
297	     * Build the customer code for a newly created owner, formatted
298	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the region derived from the
299	     * owner's postcode (falling back to the city, or {@code 'UNKNOWN'}, via the same
300	     * derivation the locality uses), and {@code HASH8} is the first eight upper-case
301	     * hex characters of the SHA-256 of the owner's normalized telephone concatenated
302	     * with its last name. This identity carries no sequence number.
303	     */
304	    private String customerCode(Owner owner) {
305	        String region = owner.getLocality();
306	        String hash8 = customerCodeHash(owner.getTelephone(), owner.getLastName());
307	        String base = region + "-" + hash8;
308	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
309	            .map(Owner::getCustomerCode)
310	            .filter(java.util.Objects::nonNull)
311	            .collect(java.util.stream.Collectors.toSet());
312	        if (!existing.contains(base)) {
313	            return base;
314	        }
315	        int n = 2;
316	        while (existing.contains(base + "-" + n)) {
317	            n++;
318	        }
319	        return base + "-" + n;
320	    }
321	
322	    /**
323	     * Compute the {@code HASH8} portion of a customer code: the first eight upper-case
324	     * hex characters of the SHA-256 digest of {@code telephone + lastName} (each
325	     * treated as empty when {@code null}), already in their normalized forms.
326	     */
327	    private String customerCodeHash(String telephone, String lastName) {
328	        String key = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
329	        try {
330	            byte[] digest = MessageDigest.getInstance("SHA-256")
331	                .digest(key.getBytes(StandardCharsets.UTF_8));
332	            StringBuilder sb = new StringBuilder();
333	            for (int i = 0; i < 4; i++) {
334	                sb.append(String.format("%02X", digest[i]));
335	            }
336	            return sb.toString();
337	        }
338	        catch (NoSuchAlgorithmException e) {
339	            throw new IllegalStateException(e);
340	        }
341	    }
342	
343	    /**
344	     * Count the existing owners whose city matches the given one, compared after
345	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
346	     * cap: a city that already holds this many owners is at capacity.
347	     */
348	    private long countOwnersInCity(String city) {
349	        String normalizedCity = normalizeForHousehold(city);
350	        return this.clinicService.findAllOwners().stream()
351	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
352	            .count();
353	    }
354	
355	    /**
356	     * Count the existing owners whose registration date falls on the given day. Used to
357	     * enforce the per-day create limit: once this many owners have been registered today,
358	     * the day is at capacity and further creates are rejected.
359	     */
360	    private long countOwnersRegisteredOn(LocalDate day) {
361	        return this.clinicService.findAllOwners().stream()
362	            .filter(existing -> day.equals(existing.getRegistrationDate()))
363	            .count();
364	    }
365	
366	    /**
367	     * Roll a registration date forward to the next business day: a date falling on a
368	     * Saturday or Sunday is advanced to the following Monday, while a weekday is
369	     * returned unchanged.
370	     */
371	    private LocalDate toBusinessDay(LocalDate date) {
372	        DayOfWeek dayOfWeek = date.getDayOfWeek();
373	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
374	            return date.plusDays(8 - dayOfWeek.getValue());
375	        }
376	        return date;
377	    }
378	
379	    /**
380	     * Find the existing owners that already belong to the same household as the given
381	     * computed household id. Because the household id is derived deterministically from
382	     * the owner's (last name, postcode), this is exactly the set of other owners sharing
383	     * that last name and postcode.
384	     */
385	    private List<Owner> findHouseholdMembers(String householdId) {
386	        if (householdId == null) {
387	            return List.of();
388	        }
389	        return this.clinicService.findAllOwners().stream()
390	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
391	            .toList();
392	    }
393	
394	    /**
395	     * Find an existing owner that this new owner softly duplicates: one sharing the same
396	     * last name (compared case-insensitively after whitespace normalization) and the same
397	     * postcode, but with a different telephone. Returns the lowest-id such owner, or
398	     * {@code null} when the new owner has no postcode or no soft match exists. Owners
399	     * whose telephone equals the new owner's are excluded, as those are governed by the
400	     * hard-duplicate (identityKey) check rather than this soft match.
401	     */
402	    private Owner findPossibleDuplicate(Owner owner) {
403	        String postcode = owner.getPostcode();
404	        if (postcode == null) {
405	            return null;
406	        }
407	        String normalizedLastName = normalizeForHousehold(owner.getLastName());
408	        String telephone = owner.getTelephone();
409	        return this.clinicService.findAllOwners().stream()
410	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
411	                && postcode.equals(existing.getPostcode())
412	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
413	            .min(java.util.Comparator.comparing(Owner::getId))
414	            .orElse(null);
415	    }
416	
417	    /**
418	     * Count the existing owners that already share both the given first and last
419	     * name, compared case-insensitively. Used to populate an owner's namesake count
420	     * at creation time, reflecting how many owners with the same name existed before
421	     * this one was created.
422	     */
423	    private int countNamesakes(String firstName, String lastName) {
424	        String normalizedFirstName = normalizeName(firstName);
425	        String normalizedLastName = normalizeName(lastName);
426	        return (int) this.clinicService.findAllOwners().stream()
427	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
428	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
429	            .count();
430	    }
431	
432	    private String normalizeName(String value) {
433	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
434	    }
435	
436	    /**
437	     * Build the deterministic identifier shared by all owners of one household: the first
438	     * 12 hex characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}.
439	     * Because it depends only on the (last name, postcode) pair, every owner at the same last
440	     * name and postcode resolves to the same value regardless of creation order.
441	     */
442	    private String householdId(String lastName, String postcode) {
443	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
444	        try {
445	            byte[] digest = MessageDigest.getInstance("SHA-256")
446	                .digest(key.getBytes(StandardCharsets.UTF_8));
447	            StringBuilder sb = new StringBuilder();
448	            for (int i = 0; i < 6; i++) {
449	                sb.append(String.format("%02x", digest[i]));
450	            }
451	            return sb.toString();
452	        }
453	        catch (NoSuchAlgorithmException e) {
454	            throw new IllegalStateException(e);
455	        }
456	    }
457	
458	    private String normalizeForHousehold(String value) {
459	        if (value == null) {
460	            return "";
461	        }
462	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
463	    }
464	
465	    /** True when the email's domain is on the disposable-provider blocklist. */
466	    private boolean isDisposableEmailDomain(String email) {
467	        if (email == null) {
468	            return false;
469	        }
470	        int at = email.lastIndexOf('@');
471	        if (at < 0 || at == email.length() - 1) {
472	            return false;
473	        }
474	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
475	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
476	    }
477	
478	    private String normalizeTelephone(String telephone) {
479	        if (telephone == null) {
480	            return null;
481	        }
482	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
483	        String digits;
484	        if (cleaned.startsWith("+")) {
485	            digits = cleaned.substring(1);
486	        } else {
487	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
488	            digits = "61" + national;
489	        }
490	        if (!digits.matches("[0-9]{8,15}")) {
491	            return null;
492	        }
493	        if (!hasValidNationalLength(digits)) {
494	            return null;
495	        }
496	        return "+" + digits;
497	    }
498	
499	    /**
500	     * Validate the national-number length of an E.164 number (the digits, without the
501	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
502	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
503	     * codes without a known rule are accepted as-is.
504	     */
505	    private boolean hasValidNationalLength(String digits) {
506	        if (digits.startsWith("61")) {
507	            return digits.length() - 2 == 9;
508	        }
509	        if (digits.startsWith("1")) {
510	            return digits.length() - 1 == 10;
511	        }
512	        return true;
513	    }
514	
515	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
516	    @Override
517	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
518	        Owner owner = this.clinicService.findOwnerById(ownerId);
519	        if (owner != null) {
520	            Pet pet = owner.getPet(petId);
521	            if (pet != null) {
522	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
523	            }
524	        }
525	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
526	    }
527	}
